// Offline support for OC HSE Audit. Generated by tools/build-sw.py, don't edit by hand.
// Every file of the app is saved on the device, so it opens and works with no internet.
const VERSION = "679d1cb7d6ef";
const CACHE = "oc-hse-audit-" + VERSION;
const FILES = [
  "./",
  "README.md",
  "assets/apple-touch-icon.png",
  "assets/icon-192.png",
  "assets/icon-512.png",
  "assets/icon-64.png",
  "assets/maskable-512.png",
  "assets/orascom-logo.png",
  "close.html",
  "css/app.css",
  "fonts/barlow-latin-400-normal.woff2",
  "fonts/barlow-latin-500-normal.woff2",
  "fonts/barlow-latin-600-normal.woff2",
  "fonts/barlow-latin-700-normal.woff2",
  "fonts/barlow-latin-800-normal.woff2",
  "fonts/barlow-semi-condensed-latin-500-normal.woff2",
  "fonts/barlow-semi-condensed-latin-600-normal.woff2",
  "fonts/barlow-semi-condensed-latin-700-normal.woff2",
  "index.html",
  "js/app.js",
  "js/close.js",
  "js/components.js",
  "js/config.js",
  "js/demo.js",
  "js/model.js",
  "js/report/export.js",
  "js/scoring.js",
  "js/seed.js",
  "js/sign.js",
  "js/store.js",
  "js/sync.js",
  "js/templates.js",
  "js/ui.js",
  "js/views/audit.js",
  "js/views/audits.js",
  "js/views/dashboard.js",
  "js/views/good.js",
  "js/views/home.js",
  "js/views/ncr.js",
  "js/views/ncrs.js",
  "js/views/plan.js",
  "js/views/projects.js",
  "js/views/report.js",
  "js/views/settings.js",
  "js/views/team.js",
  "js/widgets.js",
  "manifest.webmanifest",
  "vendor/echarts.min.js",
  "vendor/exceljs.min.js",
  "vendor/pptxgen.bundle.js",
  "vendor/supabase.js"
];
self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES.map(f => new Request(f, { cache: "reload" })))));
});
self.addEventListener("activate", e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith("oc-hse-audit-") && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});
self.addEventListener("message", e => { if (e.data === "update") self.skipWaiting(); });
self.addEventListener("fetch", e => {
  const req = e.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || !url.pathname.startsWith(new URL(self.registration.scope).pathname)) return;
  e.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(req, { ignoreSearch: true }) || (req.mode === "navigate" ? await cache.match("./") : null);
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res.ok) cache.put(req, res.clone());
      return res;
    } catch (err) {
      return new Response("Offline and this file isn't saved on the device yet.", { status: 503, headers: { "Content-Type": "text/plain" } });
    }
  })());
});
